import React from "react";
import { AbsoluteFill, useCurrentFrame } from "remotion";
import { COLORS } from "../style-tokens";
import type { PrimitiveProps } from "../primitives";

// Two dot grids painted as repeating radial-gradients. Motion = background-position
// taken modulo the cell size, so the phase is periodic and the drift never ends,
// never settles and never overflows — any clip length looks identical.
const CELL_FRONT = 128;
const CELL_BACK = 210;
const RADIUS_FRONT = 13;
const RADIUS_BACK = 7;
const SPEED_FRONT = 95; // px/s along the up-right diagonal (medium fast)
const SPEED_BACK = 40;

const wrap = (value: number, cell: number): number => ((value % cell) + cell) % cell;

const DotLayer: React.FC<{
  cell: number;
  radius: number;
  x: number;
  y: number;
  opacity: number;
}> = ({ cell, radius, x, y, opacity }) => (
  <AbsoluteFill
    style={{
      backgroundImage: `radial-gradient(circle, ${COLORS.ink} 0 ${radius}px, transparent ${radius + 1}px)`,
      backgroundSize: `${cell}px ${cell}px`,
      backgroundPosition: `${x}px ${y}px`,
      opacity,
    }}
  />
);

const BallGridDrift: React.FC<PrimitiveProps> = ({ fps }) => {
  const frame = useCurrentFrame();
  const seconds = frame / Math.max(1, fps);

  // 0.707 ≈ cos/sin 45° — equal push right and up.
  const frontTravel = seconds * SPEED_FRONT * 0.707;
  const backTravel = seconds * SPEED_BACK * 0.707;

  // Slow, endless breathing of the ink density (13 s period) so the field never
  // reads as a frozen texture.
  const breathe = Math.sin((2 * Math.PI * seconds) / 13);

  return (
    <AbsoluteFill style={{ backgroundColor: COLORS.papyrus }}>
      <DotLayer
        cell={CELL_BACK}
        radius={RADIUS_BACK}
        x={wrap(backTravel, CELL_BACK)}
        y={wrap(-backTravel, CELL_BACK)}
        opacity={0.16 + breathe * 0.02}
      />
      <DotLayer
        cell={CELL_FRONT}
        radius={RADIUS_FRONT}
        x={wrap(frontTravel, CELL_FRONT)}
        y={wrap(-frontTravel, CELL_FRONT)}
        opacity={0.3 + breathe * 0.03}
      />
      {/* Soft edge fall-off keeps the centre clear for foreground content. */}
      <AbsoluteFill
        style={{
          backgroundImage: `radial-gradient(120% 78% at 50% 44%, transparent 42%, ${COLORS.ink} 100%)`,
          opacity: 0.34,
        }}
      />
    </AbsoluteFill>
  );
};

export default BallGridDrift;
